"""Feedback loop: sample vs README tables + invariants on full dataset.

Usage: python loop.py <repo_root>
Exit 0 = green, 1 = red.
"""
import json
import re
import subprocess
import sys
from decimal import Decimal
from pathlib import Path

root = Path(sys.argv[1]).resolve()
py = sys.executable
failures = []


def run(inp, out, top=5):
    env = {"PYTHONPATH": str(root / "src"), "SYSTEMROOT": "C:\\Windows", "PYTHONIOENCODING": "utf-8"}
    p = subprocess.run(
        [py, "-m", "onfly_report", "--input", str(root / inp), "--rates", str(root / "data/taxas_cambio.csv"),
         "--output", str(out), "--top", str(top)],
        cwd=root, env=env, capture_output=True, text=True, encoding="utf-8",
    )
    if p.returncode != 0:
        failures.append(f"{inp}: exit {p.returncode}: {p.stderr[-300:]}")
        return None
    return json.loads(Path(out).read_text(encoding="utf-8"))


# --- README sample block ---
readme = (root / "README.md").read_text(encoding="utf-8")
block = readme.split("<!-- AMOSTRA:INICIO -->")[1].split("<!-- AMOSTRA:FIM -->")[0]
tables, cur = [], []
for line in block.splitlines():
    if line.startswith("|"):
        cur.append([c.strip().replace("\\_", "_").strip("`") for c in line.strip("|").split("|")])
    elif cur:
        tables.append(cur); cur = []
if cur:
    tables.append(cur)
summary_t, month_t, hotels_t = [t[2:] for t in tables]  # skip header + separator

tmp = Path(sys.argv[2]) if len(sys.argv) > 2 else Path(__file__).parent
r = run("data/exemplo-validacao.csv", tmp / "sample.json")
if r:
    for k, v in summary_t:
        got = str(r["summary"][k])
        if got != v:
            failures.append(f"sample summary.{k}: got {got} want {v}")
    got_m = [[m["month"], str(m["reservations"]), str(m["room_nights"]), m["total_brl"]] for m in r["by_month"]]
    if got_m != month_t:
        failures.append(f"sample by_month: got {got_m} want {month_t}")
    got_h = [[h["hotel_id"], h["hotel_name"], str(h["room_nights"]), h["total_brl"]] for h in r["top_hotels"]]
    if got_h != hotels_t:
        failures.append(f"sample top_hotels: got {got_h} want {hotels_t}")

# --- invariants on full dataset ---
for top in (5, 1000):
    f = run("data/reservas_hoteis.csv", tmp / f"full_{top}.json", top)
    if not f:
        continue
    s = f["summary"]
    tag = f"full(top={top})"
    if s["confirmed_reservations"] + s["cancelled_reservations"] + s["no_show_reservations"] != s["total_reservations"]:
        failures.append(f"{tag}: status counts don't add up to total ({s})")
    if sum(m["reservations"] for m in f["by_month"]) != s["confirmed_reservations"]:
        failures.append(f"{tag}: sum(by_month.reservations) != confirmed")
    if sum(m["room_nights"] for m in f["by_month"]) != s["total_room_nights"]:
        failures.append(f"{tag}: sum(by_month.room_nights) != total_room_nights")
    if s["total_room_nights"] < 0 or any(m["room_nights"] <= 0 for m in f["by_month"]):
        failures.append(f"{tag}: non-positive room_nights")
    months = [m["month"] for m in f["by_month"]]
    if months != sorted(months):
        failures.append(f"{tag}: by_month not ascending")
    keys = [(-Decimal(h["total_brl"]), h["hotel_id"]) for h in f["top_hotels"]]
    if keys != sorted(keys):
        failures.append(f"{tag}: top_hotels not sorted by numeric total_brl desc, hotel_id asc")
    for fld in ["total_amount_brl", "average_nightly_rate_brl"]:
        if not re.fullmatch(r"-?\d+\.\d{2}", s[fld]):
            failures.append(f"{tag}: {fld} bad format {s[fld]!r}")
    diff = abs(sum(Decimal(m["total_brl"]) for m in f["by_month"]) - Decimal(s["total_amount_brl"]))
    if diff > Decimal("0.01") * len(f["by_month"]):
        failures.append(f"{tag}: by_month total_brl sum differs from total by {diff}")
    if top == 1000:
        print(f"{tag}: hotels with billable reservations = {len(f['top_hotels'])}")

for x in failures:
    print("RED  ", x)
print("GREEN" if not failures else f"RED: {len(failures)} failure(s)")
sys.exit(1 if failures else 0)

