Usage: python loop.py <repo_root>
Exit 0 = green, 1 = red.
"""
import json
import re
import subprocess
import sys
from decimal import Decimal
from pathlib import Path

root = Path(sys.argv[1]).resolve()
py = sys.executable
failures = []


def run(inp, out, top=5):
    env = {"PYTHONPATH": str(root / "src"), "SYSTEMROOT": "C:\\Windows", "PYTHONIOENCODING": "utf-8"}
    p = subprocess.run(
        [py, "-m", "onfly_report", "--input", str(root / inp), "--rates", str(root / "data/taxas_cambio.csv"),
         "--output", str(out), "--top", str(top)],
        cwd=root, env=env, capture_output=True, text=True, encoding="utf-8",
    )
    if p.returncode != 0:
        failures.append(f"{inp}: exit {p.returncode}: {p.stderr[-300:]}")
        return None
    return json.loads(Path(out).read_text(encoding="utf-8"))


# --- README sample block ---
readme = (root / "README.md").read_text(encoding="utf-8")
block = readme.split("<!-- AMOSTRA:INICIO -->")[1].split("<!-- AMOSTRA:FIM -->")[0]
tables, cur = [], []
for line in block.splitlines():
    if line.startswith("|"):
        cur.append([c.strip().replace("\\_", "_").strip("`") for c in line.strip("|").split("|")])
    elif cur:
        tables.append(cur); cur = []
if cur:
    tables.append(cur)
summary_t, month_t, hotels_t = [t[2:] for t in tables]  # skip header + separator

tmp = Path(sys.argv[2]) if len(sys.argv) > 2 else Path(__file__).parent
r = run("data/exemplo-validacao.csv", tmp / "sample.json")
if r:
    for k, v in summary_t:
        got = str(r["summary"][k])
        if got != v:
            failures.append(f"sample summary.{k}: got {got} want {v}")
    got_m = [[m["month"], str(m["reservations"]), str(m["room_nights"]), m["total_brl"]] for m in r["by_month"]]
    if got_m != month_t:
        failures.append(f"sample by_month: got {got_m} want {month_t}")
    got_h = [[h["hotel_id"], h["hotel_name"], str(h["room_nights"]), h["total_brl"]] for h in r["top_hotels"]]
    if got_h != hotels_t:
